function [m_year] = propellant_per_year(m_p, n_day, n_rcs)
%PROPELLANT_PER_YEAR  The propellant of a year of slews: m_p n_day 365.25 when thrusters are fitted, else 0.
%   m_p: real[kg] (passed in kg)
%   n_day: real[1] (passed a plain number)
%   n_rcs: int (passed a whole number)
%   returns m_year: real[kg] (passed in kg)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    m_year = 0;
    if (n_rcs > 0)
        m_year = ((m_p * n_day) * 365.25);
    else
        m_year = 0;
    end
end
